}
.snm-card-header .snm-card-title {
  font-weight: 700;
  letter-spacing: 0.2px;
  flex: 1;
  text-align: center;
  pointer-events: none;
}
.snm-card-header .snm-card-toggle {
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: #7fd7cf;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
