}
.snm-card-header .snm-affection-status.snm-status-locked .snm-status-text {
  color: #ffd1d8;
}
.snm-card-header .snm-affection-status.snm-status-partial {
  background: rgba(91, 91, 33, 0.6);
  border: 1px solid rgba(140, 138, 42, 0.4);
