  grid-template-columns: 120px 1fr;
  gap: 6px 4px;
  max-height: 500px;
  opacity: 1;
  overflow: hidden;
  transition: max-height 0.3s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.25s ease-in-out, padding 0.3s ease;
}

.snm-row {
  display: contents;
}
.snm-row .k {
  color: #7fae94;
  align-self: center;
  padding-right: 4px;
}
.snm-row .k::before {
  content: attr(data-emoji);
