  border: 1px solid #144545;
}
.snm-progress .fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 0%;
  background: linear-gradient(90deg, #14b3a9, #6cf2df);
}

.snm-num {
  min-width: 40px;
  padding: 3px 10px;
  border-radius: 999px;
