  border: 1px solid #1a5759;
  color: #d8fff6;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  text-align: center;
  line-height: 1.2;
  font-size: 12px;
}

.snm-num--ok {
  background: #0e3735;
  border-color: #1a6c68;
  color: #c7fff4;
}

.snm-num--warn {
  background: #3a3a21;
  border-color: #6b6a2a;
  color: #f1efb0;
}

.snm-num--danger {
  background: #3a2628;
  border-color: #6a333a;
  color: #ffd1d8;
}

.snm-tier {
  color: #a9d7d1;
  font-size: 12px;
}

.snm-progress--desire-warn .fill {
  background: linear-gradient(90deg, #b8a83d, #d4c441);
}

.snm-progress--desire-high .fill {
  background: linear-gradient(90deg, #d4743d, #ff8c42);
}

.snm-progress--desire-danger .fill {
  background: linear-gradient(90deg, #d43d46, #e63946);
}

.snm-num--desire-warn {
  background: #3d3a1e;
  border-color: #6b6a2a;
  color: #d4c441;
}

.snm-num--desire-high {
  background: #3d2b1e;
  border-color: #6b4a2a;
  color: #ff8c42;
}

.snm-num--desire-danger {
  background: #3d1e23;
  border-color: #6b2a33;
  color: #e63946;
}

.snm-sync-indicator {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 12px;
  margin: 8px 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
}
.snm-sync-indicator.snm-desync {
  background: rgba(91, 91, 33, 0.3);
  border: 1px solid rgba(140, 138, 42, 0.6);
  color: #f1efb0;
}
.snm-sync-indicator .snm-sync-icon {
  font-size: 14px;
}
.snm-sync-indicator .snm-sync-text {
  flex: 1;
  text-align: center;
  letter-spacing: 0.2px;
}
