  color: #f5f3c0;
  cursor: pointer;
  font-size: 11px;
  transition: all 0.2s ease;
}
.snm-sync-indicator .snm-sync-button:hover {
  background: rgba(140, 138, 42, 0.6);
  transform: translateY(-1px);
}
.snm-sync-indicator .snm-sync-button:active {
  transform: translateY(0);
}

@media (orientation: portrait), (max-width: 680px) {
  .snm-sync-indicator {
    padding: 6px 10px;
    font-size: 11px;
    gap: 6px;
  }
  .snm-sync-indicator .snm-sync-icon {
    font-size: 12px;
  }
  .snm-sync-indicator .snm-sync-button {
    padding: 3px 6px;
    font-size: 10px;
  }
}
